```openscad
// L-shaped mounting bracket
// Print orientation: base plate flat on the bed (z = 0), vertical plate builds upward.
// Coordinates follow the user's spec directly (X centred on origin, Y from 0).

$fn = 64;

// ---------- Base plate ----------
base_x_min   = -20;   // base plate X start
base_x_max   = 20;    // base plate X end
base_y_min   = 0;     // base plate Y start (back edge)
base_y_max   = 45;    // base plate Y end (front edge)
base_thk     = 5;     // base plate thickness (Z)

// ---------- Vertical plate ----------
vert_y_min   = 0;     // vertical plate Y start
vert_y_max   = 5;     // vertical plate Y end (thickness)
vert_height  = 50;    // vertical plate height (Z)

// ---------- Holes ----------
hole_d       = 4.5;   // through-hole diameter (all holes)
base_hole_x  = 14;    // +/- X position of base holes
base_hole_y  = 30;    // Y position of base holes
vert_hole_x  = 14;    // +/- X position of vertical-plate holes
vert_hole_z  = 35;    // Z position of vertical-plate holes

eps          = 0.5;   // cutter overshoot past faces

// Derived
plate_w = base_x_max - base_x_min;   // 40 mm width

difference() {
    union() {
        // Base plate
        translate([base_x_min, base_y_min, 0])
            cube([plate_w, base_y_max - base_y_min, base_thk]);

        // Vertical plate on back edge
        translate([base_x_min, vert_y_min, 0])
            cube([plate_w, vert_y_max - vert_y_min, vert_height]);
    }

    // Vertical (Z) through-holes in base plate
    for (sx = [-1, 1])
        translate([sx * base_hole_x, base_hole_y, -eps])
            cylinder(d = hole_d, h = base_thk + 2 * eps);

    // Horizontal (Y) through-holes in vertical plate
    for (sx = [-1, 1])
        translate([sx * vert_hole_x, vert_y_min - eps, vert_hole_z])
            rotate([-90, 0, 0])
                cylinder(d = hole_d, h = (vert_y_max - vert_y_min) + 2 * eps);
}
