```openscad
// 6-well agarose gel comb - printed flat on the bed
// Units: mm

$fn = 64;

// ---- Dimensions ----
plate_t     = 2.0;   // plate thickness (Z)
spine_len   = 44;    // spine length (X)
spine_w     = 12;    // spine width (Y)
n_teeth     = 6;     // number of teeth / wells
tooth_w     = 4.0;   // tooth width (X)
tooth_len   = 16;    // tooth length (Y), hanging in -Y
tooth_gap   = 2.0;   // gap between neighbouring teeth (X)
overlap     = 0.5;   // teeth overlap into spine for a clean union

// ---- Derived ----
row_w      = n_teeth * tooth_w + (n_teeth - 1) * tooth_gap; // total width of tooth row
total_y    = spine_w + tooth_len;                           // overall Y extent
y_min      = -total_y / 2;                                  // bottom (tooth tips)
spine_y0   = y_min + tooth_len;                             // spine lower edge
row_x0     = -row_w / 2;                                    // left edge of tooth row

// ---- Model ----
union() {
    // Spine (back bar)
    translate([-spine_len / 2, spine_y0, 0])
        cube([spine_len, spine_w, plate_t]);

    // Teeth
    for (i = [0 : n_teeth - 1])
        translate([row_x0 + i * (tooth_w + tooth_gap), y_min, 0])
            cube([tooth_w, tooth_len + overlap, plate_t]);
}
```

```openscad
// Rigid in-line rod coupler - printed upright along Z
$fn = 96;

// ---- Dimensions (mm) ----
outer_d   = 16.0;   // coupler outer diameter
length    = 22.0;   // coupler length (Z)
bore_d    = 6.0;    // axial rod bore diameter
screw_d   = 5.0;    // radial set-screw hole diameter
screw_z1  = length * 0.25;  // first set-screw height (1/4 length)
screw_z2  = length * 0.75;  // second set-screw height (3/4 length)
eps       = 0.5;    // overcut for clean differences

screw_heights = [screw_z1, screw_z2];

difference() {
    // Main body
    cylinder(d = outer_d, h = length);

    // Axial bore through full length
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = length + 2 * eps);

    // Radial set-screw holes on +X side (from axis out through wall)
    for (z = screw_heights)
        translate([0, 0, z])
            rotate([0, 90, 0])
                cylinder(d = screw_d, h = outer_d / 2 + eps, $fn = 64);
}
```

```openscad
// Small lab funnel - printed upright, wide opening at top
// Built as a rotate_extrude of a 2D wall profile. Open at both ends.

$fn = 128;

// ---------------- Dimensions (mm) ----------------
spout_od      = 12.0;   // spout outer diameter
spout_top_z   = 25.0;   // spout runs z = 0 .. 25
rim_od        = 50.0;   // cone outer diameter at rim
rim_z         = 65.0;   // rim height (top of funnel)
wall          = 1.6;    // wall thickness everywhere (normal to surface)

// ---------------- Derived values ----------------
spout_or  = spout_od / 2;                 // 6.0  spout outer radius
spout_ir  = spout_or - wall;              // 4.4  spout bore radius (8.8 mm bore)
rim_or    = rim_od / 2;                   // 25.0 rim outer radius
cone_h    = rim_z - spout_top_z;          // 40   cone height
cone_k    = (rim_or - spout_or) / cone_h; // radial growth per mm of height
// Radial offset that gives a true 1.6 mm wall measured normal to the cone surface
cone_dr   = wall * sqrt(1 + cone_k * cone_k);
// Inner cone surface: r = spout_or + (z - spout_top_z)*k - cone_dr
// Height where inner cone meets the spout bore (r = spout_ir)
inner_join_z = spout_top_z + (spout_ir - spout_or + cone_dr) / cone_k;
rim_ir    = rim_or - cone_dr;             // inner radius at rim

// ---------------- Model ----------------
module funnel() {
    rotate_extrude(convexity = 4)
        polygon(points = [
            [spout_ir, 0],              // bottom of bore
            [spout_or, 0],              // bottom outer edge
            [spout_or, spout_top_z],    // spout/cone outer junction
            [rim_or,   rim_z],          // rim outer edge
            [rim_ir,   rim_z],          // rim inner edge
            [spout_ir, inner_join_z]    // cone/bore inner junction
        ]);
}

funnel();
```

```openscad
// Flat drilling / marking jig
// Plate with 3 x 5 grid of through-holes and +Y orientation notch

// ---------- Plate ----------
plate_x      = 52;    // plate length (X)
plate_y      = 82;    // plate width (Y)
plate_t      = 6;     // plate thickness (Z)

// ---------- Hole grid ----------
hole_d       = 6.0;   // through-hole diameter
hole_cols    = 3;     // number of holes along X
hole_rows    = 5;     // number of holes along Y
hole_pitch_x = 15;    // centre-to-centre spacing in X
hole_pitch_y = 15;    // centre-to-centre spacing in Y

// ---------- Orientation notch (+Y edge) ----------
notch_w      = 10;    // notch width (X)
notch_d      = 5;     // notch depth in from +Y edge (Y)

// ---------- Misc ----------
eps          = 0.5;   // cutter overlap past faces
$fn          = 64;    // curve resolution

difference() {
    // Plate, centred in XY, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // 3 x 5 grid of through-holes, centred on the plate
    for (i = [0 : hole_cols - 1])
        for (j = [0 : hole_rows - 1])
            translate([(i - (hole_cols - 1)/2) * hole_pitch_x,
                       (j - (hole_rows - 1)/2) * hole_pitch_y,
                       -eps])
                cylinder(d = hole_d, h = plate_t + 2*eps, $fn = 64);

    // Rectangular orientation notch on +Y edge, centred on the Y axis
    translate([-notch_w/2, plate_y/2 - notch_d, -eps])
        cube([notch_w, notch_d + eps, plate_t + 2*eps]);
}
