```openscad
// Bench rack for 50 x 15 mL conical tubes
// Print orientation: flat on the bed, holes open upward.

// ---------------- Parameters ----------------
block_len   = 234;   // block length (X)
block_wid   = 124;   // block width (Y)
block_h     = 32;    // block height (Z)

cols        = 10;    // holes along X
rows        = 5;     // holes along Y
pitch       = 22;    // centre-to-centre spacing, X and Y

hole_d      = 17.5;  // hole diameter
hole_depth  = 28;    // hole depth from top surface
floor_t     = block_h - hole_depth; // solid floor thickness (4 mm)

eps         = 0.5;   // overshoot for clean boolean cuts
$fn         = 96;    // curve resolution

// Grid offsets so the hole grid is centred on the block
x0 = -(cols - 1) * pitch / 2;
y0 = -(rows - 1) * pitch / 2;

// ---------------- Model ----------------
difference() {
    // Solid block, centred in XY, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // 5 x 10 grid of blind holes, open at the top
    for (i = [0 : cols - 1])
        for (j = [0 : rows - 1])
            translate([x0 + i * pitch, y0 + j * pitch, floor_t])
                cylinder(d = hole_d, h = hole_depth + eps);
}
```

```openscad
// Snap-on C-clip for 8.0 mm lab-stand rod
// Printed flat: 2-D profile in XY, extruded 12 mm in +Z

// ---- Dimensions (mm) ----
rod_d      = 8.0;              // inner diameter (rod)
wall       = 4.0;              // ring wall thickness
outer_d    = rod_d + 2*wall;   // outer diameter = 16.0
height     = 12.0;             // extrusion height (Z)
gap_w      = 5.0;              // opening width (Y), on -X side
eps        = 0.5;              // overcut for clean booleans

$fn = 128;

// ---- 2-D profile ----
module clip_profile() {
    difference() {
        circle(d = outer_d);
        circle(d = rod_d);
        // opening: x < 0, -gap_w/2 < y < gap_w/2
        translate([-(outer_d/2 + eps), -gap_w/2])
            square([outer_d/2 + eps, gap_w]);
    }
}

// ---- Part ----
linear_extrude(height = height)
    clip_profile();
```

```openscad
// Two-part enclosure: open-top box + upside-down lid, printed side by side
// Units: mm

$fn = 64;

// ---------------- Box ----------------
box_x     = 70.0;   // outer length (X)
box_y     = 45.0;   // outer width (Y)
box_z     = 35.0;   // outer height (Z)
wall      = 2.0;    // side wall thickness
floor_t   = 2.0;    // floor thickness

// ---------------- Lid ----------------
lid_x     = 70.0;   // plate length (X)
lid_y     = 45.0;   // plate width (Y)
lid_t     = 3.0;    // plate thickness
lip_x     = 65.4;   // lip outer length (box inner 66 - 2*0.3 clearance)
lip_y     = 40.4;   // lip outer width  (box inner 41 - 2*0.3 clearance)
lip_wall  = 2.0;    // lip wall thickness
lip_h     = 3.0;    // lip height above plate

// ---------------- Layout ----------------
gap       = 10.0;   // gap between parts on the bed
eps       = 0.5;    // cutter overshoot
ovl       = 0.01;   // union overlap

total_x   = box_x + gap + lid_x;        // overall footprint length
box_cx    = -total_x/2 + box_x/2;       // box centre X
lid_cx    =  total_x/2 - lid_x/2;       // lid centre X

// ---------------- Parts ----------------
module box() {
    difference() {
        translate([-box_x/2, -box_y/2, 0])
            cube([box_x, box_y, box_z]);
        translate([-(box_x - 2*wall)/2, -(box_y - 2*wall)/2, floor_t])
            cube([box_x - 2*wall, box_y - 2*wall, box_z - floor_t + eps]);
    }
}

module lid() {
    union() {
        // plate on the bed
        translate([-lid_x/2, -lid_y/2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip on top of plate
        difference() {
            translate([-lip_x/2, -lip_y/2, lid_t - ovl])
                cube([lip_x, lip_y, lip_h + ovl]);
            translate([-(lip_x - 2*lip_wall)/2, -(lip_y - 2*lip_wall)/2, lid_t - eps])
                cube([lip_x - 2*lip_wall, lip_y - 2*lip_wall, lip_h + 2*eps]);
        }
    }
}

translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
```

```openscad
// 5-place HPLC vial holder - printed upright
// Units: mm

// ---- Block ----
block_length = 100;   // X
block_width  = 28;    // Y
block_height = 20;    // Z

// ---- Vial holes ----
hole_count   = 5;     // number of vial positions
hole_pitch   = 18;    // centre-to-centre spacing along X
hole_dia     = 11.6;  // vial hole diameter
hole_depth   = 17;    // depth from top surface
floor_thick  = block_height - hole_depth; // 3 mm floor

// ---- Cutting overlap ----
eps = 0.5;            // extension past top face for clean cuts

$fn = 96;

difference() {
    // Solid block centred in X/Y, resting on z = 0
    translate([-block_length/2, -block_width/2, 0])
        cube([block_length, block_width, block_height]);

    // Row of blind holes centred in X and Y
    for (i = [0 : hole_count - 1]) {
        x = (i - (hole_count - 1)/2) * hole_pitch;
        translate([x, 0, floor_thick])
            cylinder(d = hole_dia, h = hole_depth + eps, $fn = 96);
    }
}
