```openscad
// Push-on cap for a 12.0 mm OD tube, printed open-end up
$fn = 96;

// --- Dimensions (mm) ---
tube_od      = 12.0;   // tube outer diameter (reference)
clearance    = 0.4;    // diametral clearance over tube
cap_od       = 17.8;   // cap outer diameter
cap_h        = 14;     // total cap height
bore_d       = 12.8;   // blind bore diameter (tube_od + clearance)
floor_t      = 3.0;    // closed end thickness at bottom
groove_n     = 8;      // number of grip grooves
groove_d     = 2;      // grip groove diameter (half-cylinder on outer surface)
eps          = 0.5;    // cutter overshoot

difference() {
    // main body
    cylinder(d = cap_od, h = cap_h);

    // blind bore from top
    translate([0, 0, floor_t])
        cylinder(d = bore_d, h = cap_h - floor_t + eps);

    // vertical grip grooves, centred on outer surface
    for (i = [0 : groove_n - 1])
        rotate([0, 0, i * 360 / groove_n])
            translate([cap_od / 2, 0, -eps])
                cylinder(d = groove_d, h = cap_h + 2 * eps, $fn = 48);
}
