```openscad
// Replacement control knob for 6.0 mm D-shaft
// Print orientation: hotplate-facing side (bore opening) down on the bed

$fn = 96;

// ---- Knob body ----
knob_d      = 22.0;   // knob outer diameter
knob_h      = 18.0;   // knob total height

// ---- D-shaped blind bore ----
bore_d      = 6.2;    // bore circle diameter (clearance for 6.0 mm shaft)
bore_flat   = 4.9;    // distance from flat to opposite side of circle
bore_depth  = 15.0;   // blind bore depth from bottom face

// ---- Grip grooves ----
groove_n    = 16;     // number of grooves
groove_d    = 2.0;    // groove (half-cylinder) diameter, centred on outer surface

// ---- Misc ----
eps         = 0.5;    // overshoot for clean boolean cuts

// Derived
bore_r      = bore_d / 2;
flat_x      = -bore_r + bore_flat;   // X position of the flat (from centre)

// 2D D-profile of the bore
module d_profile() {
    intersection() {
        circle(r = bore_r);
        translate([-bore_r - 1, -bore_r - 1])
            square([flat_x + bore_r + 1, bore_d + 2]);
    }
}

difference() {
    // Main body
    cylinder(d = knob_d, h = knob_h);

    // D-shaped blind bore from bottom face
    translate([0, 0, -eps])
        linear_extrude(height = bore_depth + eps)
            d_profile();

    // Vertical grip grooves along full height
    for (i = [0 : groove_n - 1])
        rotate([0, 0, i * 360 / groove_n])
            translate([knob_d / 2, 0, -eps])
                cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 48);
}
```

