// Adapter sleeve: lets a narrow tube sit in a wider rack hole
// Print orientation: upside down, collar on the bed (z = 0), sleeve rising to z = 21.5

$fn = 96;               // smoothness of curved surfaces

// --- Dimensions (mm) ---
collar_d      = 14.0;   // collar outer diameter
collar_h      = 2.0;    // collar thickness (z = 0 to 2.0)
sleeve_od     = 11.5;   // sleeve body outer diameter
total_h       = 21.5;   // overall height (top of sleeve)
bore_d        = 6.5;    // straight through-bore diameter
eps           = 0.5;    // overshoot for clean boolean cuts
overlap       = 0.01;   // small overlap so collar and sleeve fuse

sleeve_h = total_h - collar_h;  // sleeve body height above collar

difference() {
    union() {
        // Collar lying on the bed
        cylinder(d = collar_d, h = collar_h);

        // Sleeve body rising from the collar
        translate([0, 0, collar_h - overlap])
            cylinder(d = sleeve_od, h = sleeve_h + overlap);
    }

    // Straight through-bore, open at both ends
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
