// Weighted base for vertical support rod
// Printed upright: disc on bed, boss rising along +Z

$fn = 96;

// --- Dimensions (mm) ---
base_d        = 80.0;   // base disc diameter
base_h        = 8.0;    // base disc thickness (z = 0..8)
boss_d        = 18.0;   // central boss diameter
boss_top_z    = 26.0;   // top of boss (absolute z)
bore_d        = 6.0;    // rod bore diameter
bore_bottom_z = 8.0;    // bottom of blind bore (absolute z)
screw_d       = 5.0;    // radial set-screw hole diameter
screw_z       = 20.0;   // set-screw hole axis height (absolute z)
eps           = 0.5;    // cutter overrun past faces

difference() {
    union() {
        // Base disc
        cylinder(d = base_d, h = base_h);
        // Central boss (starts slightly inside the disc to fuse)
        translate([0, 0, base_h - eps])
            cylinder(d = boss_d, h = boss_top_z - base_h + eps);
    }

    // Blind rod bore from top of boss down to z = 8
    translate([0, 0, bore_bottom_z])
        cylinder(d = bore_d, h = boss_top_z - bore_bottom_z + eps);

    // Radial set-screw hole from +X side into the bore
    translate([0, 0, screw_z])
        rotate([0, 90, 0])
            cylinder(d = screw_d, h = boss_d / 2 + eps);
}
