```openscad
// L-shaped mounting bracket
// Print orientation: base plate flat on the bed (z = 0), vertical plate along back edge (y = 0)

$fn = 64;

// ---- Base plate ----
base_x_min   = -25;   // base plate X start
base_x_max   = 25;    // base plate X end
base_y_min   = 0;     // base plate Y start (back edge)
base_y_max   = 50;    // base plate Y end (front edge)
base_thk     = 4;     // base plate thickness (Z)

// ---- Vertical plate ----
vert_x_min   = -25;   // vertical plate X start
vert_x_max   = 25;    // vertical plate X end
vert_thk     = 4;     // vertical plate thickness (Y, from y = 0)
vert_height  = 50;    // vertical plate height (Z)

// ---- Holes ----
hole_d       = 4.5;           // mounting hole diameter
base_hole_x  = [-19, 19];     // base hole X positions
base_hole_y  = 38;            // base hole Y position
vert_hole_x  = [-19, 19];     // vertical plate hole X positions
vert_hole_z  = 32;            // vertical plate hole Z position

eps          = 0.5;           // cutter overshoot past faces

difference() {
    union() {
        // Base plate
        translate([base_x_min, base_y_min, 0])
            cube([base_x_max - base_x_min, base_y_max - base_y_min, base_thk]);

        // Vertical plate
        translate([vert_x_min, 0, 0])
            cube([vert_x_max - vert_x_min, vert_thk, vert_height]);
    }

    // Vertical through-holes in base plate (along Z)
    for (x = base_hole_x)
        translate([x, base_hole_y, -eps])
            cylinder(d = hole_d, h = base_thk + 2 * eps);

    // Horizontal through-holes in vertical plate (along Y)
    for (x = vert_hole_x)
        translate([x, -eps, vert_hole_z])
            rotate([-90, 0, 0])
                cylinder(d = hole_d, h = vert_thk + 2 * eps);
}
