// Small lab funnel - printed upright, wide opening at top
// Built as a single rotate_extrude of the wall cross-section,
// so the funnel is open at both ends.

$fn = 128;                 // smoothness of the round surfaces

// ---------- Dimensions (mm) ----------
spout_od     = 12.0;       // spout outer diameter
spout_h      = 20.0;       // spout height (z = 0 .. 20)
rim_od       = 50.0;       // cone outer diameter at the rim
total_h      = 60.0;       // rim height (top of funnel)
wall         = 2.4;        // wall thickness (normal to the surface)

// ---------- Derived values ----------
ro_spout   = spout_od / 2;                 // 6.0  spout outer radius
ri_spout   = ro_spout - wall;              // 3.6  spout bore radius (7.2 mm bore)
ro_rim     = rim_od / 2;                   // 25.0 rim outer radius
cone_h     = total_h - spout_h;            // 40.0 cone height
slope      = (ro_rim - ro_spout) / cone_h; // radial growth per mm of height
cone_ang   = atan(slope);                  // cone half-angle from vertical
wall_h     = wall / cos(cone_ang);         // horizontal wall width in the cone (keeps 2.4 mm normal thickness)
ri_rim     = ro_rim - wall_h;              // inner radius at the rim

// Height where the inner cone surface meets the spout bore
z_join     = spout_h + (ri_spout - (ro_spout - wall_h)) / slope;

// ---------- Model ----------
rotate_extrude(convexity = 4)
    polygon(points = [
        [ri_spout, 0],          // bore, bottom
        [ro_spout, 0],          // outside, bottom
        [ro_spout, spout_h],    // outside, spout/cone transition
        [ro_rim,   total_h],    // outside, rim
        [ri_rim,   total_h],    // inside, rim
        [ri_spout, z_join]      // inside, cone meets bore
    ]);
