    difference() {
        translate([-box_x/2, -box_y/2, 0])
            cube([box_x, box_y, box_z]);
        // inner cavity, open at top
        translate([-(box_x - 2*wall_t)/2, -(box_y - 2*wall_t)/2, floor_t])
            cube([box_x - 2*wall_t, box_y - 2*wall_t, box_z - floor_t + cut_ext]);
    }
}

// ---------- Part 2: lid (upside down) ----------
module lid() {
    union() {
        // plate on the bed
        translate([-lid_x/2, -lid_y/2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip wall on top of the plate
        difference() {
            translate([-lip_x/2, -lip_y/2, lid_t - eps])
                cube([lip_x, lip_y, lip_h + eps]);
            translate([-(lip_x - 2*lip_wall)/2, -(lip_y - 2*lip_wall)/2, lid_t - cut_ext])
                cube([lip_x - 2*lip_wall, lip_y - 2*lip_wall, lip_h + 2*cut_ext]);
        }
    }
}

