// ---------------- Parameters ----------------
knob_d        = 34;    // knob outer diameter
knob_h        = 14;    // knob height

bore_d        = 6.5;   // D-bore circle diameter
bore_flat     = 4.8;   // distance from flat to opposite side of circle
bore_depth    = 9;     // blind bore depth from bottom face

groove_count  = 24;    // number of grip grooves
groove_d      = 2;     // grip groove diameter (half-cylinder on outer surface)

eps           = 0.5;   // cutter overshoot past faces
$fn           = 96;    // curve resolution

// Derived
knob_r        = knob_d / 2;
bore_r        = bore_d / 2;
flat_offset   = bore_flat - bore_r;   // flat position from bore centre (+X side)

// ---------------- Modules ----------------
module d_bore() {
    translate([0, 0, -eps])
        linear_extrude(height = bore_depth + eps)
            intersection() {
                circle(r = bore_r, $fn = 64);
                // keep everything from the far side up to the flat
                translate([-bore_r - 1, -bore_r - 1])
                    square([flat_offset + bore_r + 1, bore_d + 2]);
            }
}

module grip_grooves() {
    for (i = [0 : groove_count - 1])
        rotate([0, 0, i * 360 / groove_count])
            translate([knob_r, 0, -eps])
                cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 64);
}

// ---------------- Part ----------------
difference() {
    cylinder(d = knob_d, h = knob_h);
    d_bore();
    grip_grooves();
}
