hole_x       = [-8, 8]; // X positions of hole pairs

base_hole_y  = 20;    // Y position of base plate holes
vert_hole_z  = 40;    // Z position of vertical plate holes

cut_extra    = 1;     // overshoot of cutting shapes past faces

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([base_x_min, base_y_min, 0])
            cube([base_x_max - base_x_min, base_y_max - base_y_min, base_thick]);

        // Vertical plate on back edge
        translate([vert_x_min, vert_y_min, 0])
            cube([vert_x_max - vert_x_min, vert_y_max - vert_y_min, vert_height]);
