spout_h       = 20.0;      // spout height (z = 0 .. 20)

// --- Cone ---
rim_od        = 55.0;      // outer diameter at the rim
total_h       = 50.0;      // overall height (rim at z = 50)

// --- Wall ---
wall          = 2.0;       // wall thickness (normal to the surface)

// --- Derived values ---
r_spout_o = spout_od / 2;                    // 7.0
r_spout_i = r_spout_o - wall;                // 5.0 (10.0 mm bore)
r_rim_o   = rim_od / 2;                      // 27.5
cone_h    = total_h - spout_h;               // 30.0
k         = (r_rim_o - r_spout_o) / cone_h;  // radial growth per mm of height
h_off     = wall * sqrt(1 + k * k);          // horizontal offset giving 2 mm normal wall on the cone
r_rim_i   = r_rim_o - h_off;                 // inner radius at rim
z_join_i  = spout_h + (h_off - wall) / k;    // where the inner cone meets the spout bore

// Half cross-section (r, z) revolved around the Z axis.
// Open at bottom (z = 0) and top (z = 50) - liquid runs straight through.
rotate_extrude(convexity = 4)
    polygon(points = [
        [r_spout_i, 0],          // bore, bottom
        [r_spout_o, 0],          // spout outer, bottom
        [r_spout_o, spout_h],    // spout outer, top / cone start
        [r_rim_o,   total_h],    // rim outer
        [r_rim_i,   total_h],    // rim inner
        [r_spout_i, z_join_i]    // inner cone meets bore
    ]);
