knob_h        = 15.0;   // knob total height

bore_d        = 6.2;    // D-bore circle diameter (6.0 shaft + clearance)
bore_flat     = 4.5;    // distance from the flat to the opposite side of the circle
bore_depth    = 10.0;   // blind bore depth from the bottom face

groove_count  = 20;     // number of vertical grip grooves
groove_d      = 2.0;    // grip groove diameter (half-cylinder on the surface)

eps           = 0.5;    // overcut so no faces are coplanar
$fn           = 96;     // facet count for curved shapes

// ---------------- Derived ----------------
knob_r        = knob_d / 2;
bore_r        = bore_d / 2;
flat_x        = -bore_r + bore_flat;   // X position of the flat (circle centred at origin)

// ---------------- Modules ----------------
module d_profile() {
    intersection() {
        circle(r = bore_r, $fn = 96);
        // keep everything from the far side of the circle up to the flat
        translate([-bore_r - eps, -bore_r - eps])
            square([bore_flat + eps, bore_d + 2 * eps]);
    }
}

module knob() {
    difference() {
        // main body
        cylinder(d = knob_d, h = knob_h, $fn = 128);

        // D-shaped blind bore from the bottom face
        translate([0, 0, -eps])
            linear_extrude(height = bore_depth + eps)
                d_profile();

        // vertical grip grooves, centred on the outer surface
        for (i = [0 : groove_count - 1])
            rotate([0, 0, i * 360 / groove_count])
                translate([knob_r, 0, -eps])
                    cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 48);
    }
}

// ---------------- Build ----------------
knob();
